#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    int i = 0;
    for (auto it = v.begin(); it != v.end(); ++it) {
        cout << "第 " << i << " 格有 " << *it << " 条喵" << endl;
        i++;
    }
    return 0;
}
